{"function":"() => {
const res = [];
const walk = (root) => {
  for (const el of root.querySelectorAll('*')) {
    if (el.shadowRoot) walk(el.shadowRoot);
    const t = el.tabIndex;
    const focusableTag = el.matches('a[href],button,input,select,textarea,[tabindex]');
    if (focusableTag && t >= 0 && !el.disabled) {
      const r = el.getBoundingClientRect();
      const cs = getComputedStyle(el);
      res.push(`${el.tagName.toLowerCase()}#${el.id}.${(el.className||'').toString().slice(0,30)} name=${(el.getAttribute('aria-label')??el.textContent.trim().slice(0,25))} vis=${r.width>0&&r.height>0&&cs.visibility!=='hidden'} ${Math.round(r.x)},${Math.round(r.y)},${Math.round(r.width)}x${Math.round(r.height)}`);
    }
  }
};
walk(document);
return res.filter(s=>!s.includes('tbody')).slice(0,80);
}"}

