const r = t.getBoundingClientRect();
return {docSW: d.scrollWidth, docCW: d.clientWidth, bodySW: document.body.scrollWidth, table: [r.x, r.width], chain: chain.slice(0,8), htmlOverflow: getComputedStyle(d).overflowX, bodyOverflow: getComputedStyle(document.body).overflowX};
}"}

